import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken(); int L = (int) in.nval;
        in.nextToken(); int C = (int) in.nval;

        // blacks[r] = bitmask das colunas com peça preta na linha r
        int[] blacks = new int[L + 2];
        in.nextToken(); int P = (int) in.nval;
        for (int i = 0; i < P; i++) {
            in.nextToken(); int x = (int) in.nval;
            in.nextToken(); int y = (int) in.nval;
            blacks[x] |= 1 << (y - 1);
        }

        final int full = (1 << C) - 1;
        final int size = 1 << C;

        // supported[r]: células (não pretas) da linha r que têm pelo menos um vizinho preto
        // (esquerda/direita na própria linha, ou preto na linha de cima / de baixo)
        int[] supported = new int[L + 1];
        for (int r = 1; r <= L; r++) {
            int horiz = ((blacks[r] << 1) & full) | (blacks[r] >> 1);
            int vert = (r > 1 ? blacks[r - 1] : 0) | (r < L ? blacks[r + 1] : 0);
            supported[r] = (horiz | vert) & full & ~blacks[r];
        }

        // DP por linhas: dp[w] = máx. brancas até a linha atual, com máscara w de brancas na linha atual (-1 = inviável)
        int[] dp = new int[size];
        java.util.Arrays.fill(dp, -1);
        for (int r = 1; r <= L; r++) {
            int[] prev = dp;
            int[] cur = new int[size];
            java.util.Arrays.fill(cur, -1);
            for (int w = 0; w < size; w++) {
                // não pode sobrepor peças pretas
                if ((w & blacks[r]) != 0) continue;
                // toda branca precisa de vizinho preto (fixado pela entrada)
                if ((w & ~supported[r]) != 0) continue;
                // duas brancas vizinhas na horizontal (bits adjacentes)
                if ((w & (w << 1)) != 0) continue;

                int add = Integer.bitCount(w);
                if (r == 1) {
                    cur[w] = add;
                } else {
                    int best = -1;
                    for (int pw = 0; pw < size; pw++) {
                        int v = prev[pw];
                        // vizinhança vertical proibida entre linhas consecutivas
                        if (v >= 0 && (pw & w) == 0 && v > best) best = v;
                    }
                    if (best >= 0) cur[w] = best + add;
                }
            }
            dp = cur;
        }

        int ans = 0;
        for (int w = 0; w < size; w++) if (dp[w] > ans) ans = dp[w];
        System.out.println(ans);
    }
}
